56: using namespace std;
57: using namespace srchilite;
58: 
59: /**
60:  * how language inference should be made: NOINFERENCE = no inference at all,
61:  * INFERFIRST = inference has priority (e.g., if --infer-lang is specified),
62:  * INFERATLAST = try inference as the last chance
63:  */
64: enum InferPolicy {
65:     NOINFERENCE = 0, INFERFIRST, INFERATLAST
66: };
67: 
68: static void print_copyright();
69: static void print_reportbugs();
70: static void print_version();
71: static string inferLang(const string &inputFileName);
72: static string getMappedLang(const string &s, LangMap &langmap);
73: static void printError(const string &s);
74: static void print_cgi_header();
75: 
76: /**
77:  * Exits for a generic error (i.e., file not found)
78:  */
79: static void exitError(const string &s);
80: 
81: static string getLangFileName(InferPolicy infer, const string &inputFileName,
82:         const string &langFileName, const string &langName, LangMap &langMap);
83: 
84: static bool verbose = false;
85: static bool failsafe = false;
86: 
87: #ifdef BUILD_AS_CGI
88: #include "envmapper.h"
89: #endif // BUILD_AS_CGI
90: /**
91:  * Print progress status information (provided --quiet is not specified)
92:  * @param message
93:  */
94: #define PROGRESSINFO(message) if (!args_info.quiet_given) cerr << message;
95: 
96: int main(int argc, char * argv[]) {
97:     set_program_name(argv[0]);
98:     gengetopt_args_info args_info; // command line structure
99:     bool is_cgi = false;
100: 
101: #ifdef BUILD_AS_CGI
102:     // map environment to parameters if used as CGI
103:     char **temp_argv;
104:     temp_argv = map_environment(&argc, argv);
105:     is_cgi = temp_argv != argv;
106:     argv = temp_argv;
107: #endif // BUILD_AS_CGI
108:     if (cmdline_parser(argc, argv, &args_info) != 0) {
109:         // calls cmdline parser. The user gived bag args if it doesn't return -1
110:         return EXIT_FAILURE;
111:     }
112: 
113:     if (args_info.version_given) {
114:         print_version();
115:         print_copyright();
116:         cmdline_parser_free(&args_info);
117:         return EXIT_SUCCESS;
118:     }
119: 
120:     if (args_info.help_given || args_info.detailed_help_given) {
121:         if (args_info.detailed_help_given) {
122:             cmdline_parser_print_detailed_help();
123:         } else {
124:             cmdline_parser_print_help();
125:         }
126:         print_reportbugs();
127:         cmdline_parser_free(&args_info);
128:         return EXIT_SUCCESS;
129:     }
130: 
131:     // set possible line ranges
132:     std::shared_ptr<LineRanges> lineRanges;
133:     if (args_info.line_range_given) {
134:         lineRanges = std::shared_ptr<LineRanges>(new LineRanges);
135:         for (unsigned int i = 0; i < args_info.line_range_given; ++i) {
136:             if (lineRanges->addRange(args_info.line_range_arg[i]) != NO_ERROR) {
137:                 string invalid_range = args_info.line_range_arg[i];
138:                 cmdline_parser_free(&args_info);
139:                 exitError("invalid line range: " + invalid_range);
140:             }
141:         }
142:     }
143: 
144:     // set possible regex ranges
145:     std::shared_ptr<RegexRanges> regexRanges;
146:     if (args_info.regex_range_given) {
147:         regexRanges = std::shared_ptr<RegexRanges>(new RegexRanges);
148:         for (unsigned int i = 0; i < args_info.regex_range_given; ++i) {
149:             if (!regexRanges->addRegexRange(args_info.regex_range_arg[i])) {
150:                 string invalid_range = args_info.regex_range_arg[i];
151:                 cmdline_parser_free(&args_info);
152:                 exitError("invalid regex range: " + invalid_range);
153:             }
154:         }
155:     }
156: 
157:     if (args_info.range_context_given) {
158:         lineRanges->setContextLines(args_info.range_context_arg);
159:     }
160: 
161:     // if a stopwatch is created, when it is deleted (automatically
162:     // since we're using a shared pointer, it will print the
163:     // elapsed seconds.
164:     std::shared_ptr<StopWatch> stopwatch;
165:     if (args_info.statistics_given) {
166:         stopwatch = std::shared_ptr<StopWatch>(new StopWatch);
167:     }
168: 
169:     verbose = args_info.verbose_given;
170:     failsafe = args_info.failsafe_given;
171: 
172:     string inputFile;
173:     string outputFile;
174:     string srcLang;
175:     string outputFormat;
176:     string langFile;
177:     string outLangFile;
178:     string dataDir;
179:     string outputDir;
180: 
181:     Verbosity::setVerbosity(verbose);
182: 
183:     if (args_info.input_given)
184:         inputFile = args_info.input_arg;
185: 
186:     if (args_info.output_given)
187:         outputFile = args_info.output_arg;
188: 
189:     // for cgi force output to standard output
190:     if (is_cgi)
191:         outputFile = "STDOUT";
192: 
193:     if (args_info.src_lang_given)
194:         srcLang = args_info.src_lang_arg;
195: 
196:     if (args_info.lang_def_given)
197:         langFile = args_info.lang_def_arg;
198: 
199:     if (args_info.outlang_def_given)
200:         outLangFile = args_info.outlang_def_arg;
201: 
202:     // the default for output format is html
203:     outputFormat = args_info.out_format_arg;
204: 
205:     if (args_info.output_dir_given) {
206:         outputDir = args_info.output_dir_arg;
207:     }
208: 
209:     /*
210:      The starting default path is from Settings::retrieveDataDir() which
211:      does the heavy lifting of finding the data dir by looking at config-time
212:      values, environment variables, user settings at $HOME, etc. See settings.h
213: 
214:      From here, invoking with --data-dir=<my-datadir> overrides the above value.
215: 
216:      We also use a fallback dir which is calculated in runtime relative to this
217:      executable (by default <executable-dir>/../share/source-highlight/).
218: 
219:      this should make the package relocatable (i.e., not stuck with a fixed
220:      installation directory).
221:      Of course, the GNU standards for installation directories
222:      should be followed, but this is not a problem if you use
223:      configure and make install features.
224:     */
225: 
226:     dataDir = Settings::retrieveDataDir();
227:     if (args_info.data_dir_given)
228:         dataDir = args_info.data_dir_arg;
229: 
230:     // start_path is global fallback for dataDir - used at fileutil.h
231:     string executable_dir = get_file_path(argv[0]);
232:     if (executable_dir.size())
233:         start_path = executable_dir + RELATIVEDATADIR;
234: 
235:     try {
236:         // initialize map files
237:         LangMap langmap(dataDir, args_info.lang_map_arg);
238: 
239:         // just print the input language list and associations
240:         if (args_info.lang_list_given) {
241:             langmap.open();
242:             langmap.print();
243:             return (EXIT_SUCCESS);
244:         }
245: 
246:         LangMap outlangmap(dataDir, args_info.outlang_map_arg);
247: 
248:         // just print the input language list and associations
249:         if (args_info.outlang_list_given) {
250:             outlangmap.open();
251:             outlangmap.print();
252:             return (EXIT_SUCCESS);
253:         }
254: 
255:         string cssUrl;
256:         if (args_info.css_given)
257:             cssUrl = args_info.css_arg;
258: 
259:         string docTitle;
260:         if (args_info.title_given)
261:             docTitle = args_info.title_arg;
262: 
263:         if (args_info.check_lang_given || args_info.check_outlang_given
264:                 || args_info.show_regex_given
265:                 || args_info.show_lang_elements_given
266:                 || args_info.lang_list_given || args_info.outlang_list_given) {
267:             // FIXME just a bogus outlang file specification not to search in outlang.map
268:             outLangFile = "html.outlang";
269:         }
270: 
271:         // initialize the main source highlight object
272:         SourceHighlight sourcehighlight(getLangFileName(NOINFERENCE,
273:                 outputFile, outLangFile, outputFormat
274:                         + (cssUrl.size() ? +"-css" : ""), outlangmap));
275: 
276:         // and sets all its properties according to the command line args
277:         sourcehighlight.setDataDir(dataDir);
278: 
279:         std::shared_ptr<DebugListener> debugListener;
280: 
281:         // if a simple check is required...
282:         if (args_info.check_lang_given) {
283:             cout << "checking " << args_info.check_lang_arg << "... ";
284:             sourcehighlight.checkLangDef(args_info.check_lang_arg);
285:             // if we're here, everything went fine!
286:             cout << "OK" << endl;
287:             // otherwise an exception has already been thrown
288:             return (EXIT_SUCCESS);
289:         }
290: 
291:         if (args_info.check_outlang_given) {
292:             cout << "checking " << args_info.check_outlang_arg << "... ";
293:             sourcehighlight.checkOutLangDef(args_info.check_outlang_arg);
294:             // if we're here, everything went fine!
295:             cout << "OK" << endl;
296:             // otherwise an exception has already been thrown
297:             return (EXIT_SUCCESS);
298:         }
299: 
300:         // just print the highlightstate if show-regex is specified
301:         if (args_info.show_regex_given) {
302:             sourcehighlight.printHighlightState(args_info.show_regex_arg, cout);
303:             return (EXIT_SUCCESS);
304:         }
305: 
306:         // just print the lang elems if show-lang-elements is specified
307:         if (args_info.show_lang_elements_given) {
308:             sourcehighlight.printLangElems(args_info.show_lang_elements_arg,
309:                     cout);
310:             return (EXIT_SUCCESS);
311:         }
312: 
313:         sourcehighlight.setGenerateEntireDoc((!args_info.no_doc_given)
314:                 && (args_info.doc_given || (docTitle.size()) || cssUrl.size()));
315:         sourcehighlight.setStyleDefaultFile(args_info.style_defaults_arg);
316:         sourcehighlight.setStyleFile(args_info.style_file_arg);
317:         if (args_info.style_css_file_given)
318:             sourcehighlight.setStyleCssFile(args_info.style_css_file_arg);
319:         sourcehighlight.setGenerateVersion(args_info.gen_version_flag != 0);
320:         sourcehighlight.setCss(cssUrl);
321:         sourcehighlight.setTitle(docTitle);
322:         sourcehighlight.setOutputDir(outputDir);
323:         sourcehighlight.setLineRanges(lineRanges.get());
324:         sourcehighlight.setRegexRanges(regexRanges.get());
325:         sourcehighlight.setBinaryOutput(args_info.binary_output_given);
326: 
327:         if (args_info.debug_langdef_given) {
328:             debugListener = std::shared_ptr<DebugListener>(new DebugListener);
329:             const string debugType = args_info.debug_langdef_arg;
330:             if (debugType == "interactive")
331:                 debugListener->setInteractive(true);
332:             sourcehighlight.setHighlightEventListener(debugListener.get());
333:             // during debugging disable optimizations
334:             sourcehighlight.setOptimize(false);
335:         }
336: 
337:         int tabs = 0;
338:         if (args_info.tab_given) {
339:             tabs = args_info.tab_arg;
340:         }
341: 
342:         if (args_info.header_given)
343:             sourcehighlight.setHeaderFileName(args_info.header_arg);
344: 
345:         if (args_info.footer_given)
346:             sourcehighlight.setFooterFileName(args_info.footer_arg);
347: 
348:         bool generateLineNumbers = args_info.line_number_given
349:                 || args_info.line_number_ref_given;
350:         sourcehighlight.setGenerateLineNumbers(generateLineNumbers);
351: 
352:         if (args_info.line_number_given) {
353:             // set the line number padding char (default is always '0')
354:             sourcehighlight.setLineNumberPad(args_info.line_number_arg[0]);
355:         }
356: 
357:         if (args_info.line_number_ref_given) {
358:             sourcehighlight.setGenerateLineNumberRefs(true);
359:             sourcehighlight.setLineNumberAnchorPrefix(
360:                     args_info.line_number_ref_arg);
361:         }
362: 
363:         if (generateLineNumbers) {
364:             // when generating line numbers tabs must be translated
365:             // otherwise the output line will not be aligned
366:             // due to the presence of line numbers
367:             sourcehighlight.setTabSpaces(tabs ? tabs : 8);
368:         }
369: 
370:         if (tabs) {
371:             sourcehighlight.setTabSpaces(tabs);
372:         }
373: 
374:         // whether to give precedence to language inference
375:         InferPolicy inferPolicy = (args_info.infer_lang_given ? INFERFIRST
376:                 : INFERATLAST);
377: 
378:         RefPosition refposition = INLINE;
379:         string gen_references_arg = args_info.gen_references_arg;
380:         if (gen_references_arg == "inline")
381:             refposition = INLINE;
382:         else if (gen_references_arg == "postline")
383:             refposition = POSTLINE;
384:         else if (gen_references_arg == "postdoc")
385:             refposition = POSTDOC;
386: 
387:         std::shared_ptr<CTagsManager> ctagsManager;
388:         if (args_info.gen_references_given) {
389:             string ctags = args_info.ctags_arg;
390:             string ctags_file = args_info.ctags_file_arg;
391: 
392:             // build the additional arguments for the ctags command
393:             if (args_info.gen_references_given && ctags != "") {
394:                 if (inputFile.size()) {
395:                     ctags += " ";
396:                     ctags += inputFile;
397:                 } else if (args_info.inputs_num) {
398:                     for (unsigned int i = 0; i < (args_info.inputs_num); ++i) {
399:                         ctags += " ";
400:                         ctags += args_info.inputs[i];
401:                     }
402:                 }
403:             }
404: 
405:             // the ctags command must be executed if --ctags is specified with an empty string
406:             ctagsManager = std::shared_ptr<CTagsManager>(new CTagsManager(
407:                     ctags_file, ctags, ctags != "", refposition));
408:             sourcehighlight.setCTagsManager(ctagsManager.get());
409:         }
410: 
411:         if (args_info.range_separator_given) {
412:             sourcehighlight.setRangeSeparator(args_info.range_separator_arg);
413:         }
414: 
